    """Өмнөх тоглогчдын хожсон Gold-ийг гүйлгээний түүхээс (Player.won_gold-ийн дүрмээр) тооцно."""
    Player = apps.get_model("game", "Player")
    GoldTransaction = apps.get_model("game", "GoldTransaction")
    gain, loss = ("battle_win", "stage_complete"), ("battle_loss", "room_leave")
    for player in Player.objects.all().iterator():
        won = 0
        for reason, amount, balance in GoldTransaction.objects.filter(player=player).order_by("created", "id").values_list(
                "reason", "amount", "balance"):
            if reason in gain and amount > 0:
                won += amount
            elif reason in loss and amount < 0:
                won = max(0, won + amount)
            won = min(won, balance)
        won = min(won, player.gold)
        if won:
            Player.objects.filter(pk=player.pk).update(won_gold=won)


